    :param diag: persistence diagram in the Gudhi format.
    :type diag: list of tuples (dim, (birth, death)).
    """
def convert_diagram_to_relative(diag: Any, max_dim: Any) -> object {
    relative_betti = {};
    for p in diag {
        dim = p[0];
        if (dim <= (max_dim - 1)) {
